test('records the call', () => {
  const cart = { getApples: () => 42 };
  const spy = jest.spyOn(cart, 'getApples');   // calls through by default
  expect(priceOf(cart)).toBe(42);              // real implementation runs
  expect(spy).toHaveBeenCalledTimes(1);
  expect(spy).toHaveReturnedWith(42);
});
afterEach(() => jest.restoreAllMocks());

